import{Ct as e,Q as t,rt as n,t as r,tt as i}from"./chunks/framework.DoUI9okn.js";var a=JSON.parse(`{"title":"Billing","description":"","frontmatter":{"title":"Billing","order":4},"headers":[],"relativePath":"services/billing/index.md","filePath":"services/billing/index.md"}`),o={name:`services/billing/index.md`};function s(r,a,o,s,c,l){return e(),i(`div`,{"data-pagefind-body":!0,"data-pagefind-meta":`date:1795284828000`},[...a[0]||=[n(`<h1 id="billing-service" tabindex="-1">Billing Service <a class="header-anchor" href="#billing-service" aria-label="Permalink to “Billing Service”">​</a></h1><p>Plans, prices, subscriptions and entitlements. Stripe (sandbox) through hosted Checkout and Customer Portal. DDD + CQRS like the Note service, with a Watermill transactional outbox: domain writes and event publishes commit together. Other services read entitlements over gRPC and never cache them.</p><ul><li><a href="./domain.html">Domain</a>: class diagrams</li><li><a href="./data.html">Data</a>: database diagram</li><li><a href="./flows.html">Flows</a>: checkout and portal, entitlements, webhooks, cancellation, payer changes and crons</li></ul><h2 id="use-cases" tabindex="-1">Use cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to “Use cases”">​</a></h2><table tabindex="0"><thead><tr><th>Actor</th><th>Use case</th></tr></thead><tbody><tr><td>Workspace member</td><td>View available plans and prices; read workspace entitlements with <code>billing_read</code>.</td></tr><tr><td>Billing manager</td><td>View the workspace subscription and payer, <a href="./flows.html#checkout">start checkout</a>, open the <a href="./flows.html#customer-portal">customer portal</a>, preview or request <a href="./flows.html#cancel-now">cancel-now</a>, and <a href="./flows.html#payer-removed-and-claimed">claim payer</a>.</td></tr><tr><td>Internal service</td><td>Resolve one or many workspace <a href="./flows.html#entitlement-resolution">entitlements</a> over gRPC.</td></tr><tr><td>Administrator</td><td>List and update plans, read or update billing policy, and create or archive prices.</td></tr><tr><td>Stripe and background workers</td><td><a href="./flows.html#webhook-pipeline">Synchronize webhooks</a>, process outbox side effects and reconcile stale or pending work.</td></tr><tr><td>Note and Authorization services</td><td>Trigger cancellation on <a href="./flows.html#workspace-deletion">workspace deletion</a> or handle <a href="./flows.html#payer-removed-and-claimed">payer removal</a>.</td></tr></tbody></table><h2 id="plan-features-and-limits" tabindex="-1">Plan features and limits <a class="header-anchor" href="#plan-features-and-limits" aria-label="Permalink to “Plan features and limits”">​</a></h2><p>The HTTP API exposes the known feature flags <code>auto_commit</code> and <code>workspace_graph</code>, and limits <code>members</code>, <code>published_notes</code>, <code>note_graph_max_depth</code>, <code>auto_commit_min_interval_seconds</code>, <code>revision_history_days</code>, <code>trash_retention_days</code>, and <code>ai_credits_monthly</code>. Limits are integers of at least <code>-1</code>; <code>-1</code> means unlimited. Plan updates are partial: omitted keys remain unchanged. Unknown keys are rejected.</p><p>The billing gRPC API uses typed <code>Features</code> and <code>Limits</code> messages with optional scalar fields, so an absent value remains distinguishable from <code>false</code> or <code>0</code>. The change from string-keyed maps uses new protobuf field numbers: billing and its note, document, and AI consumers must be deployed together. Mixed versions do not exchange features or limits correctly.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h2>`,9),t(`figure`,{class:`vpd-diagram vpd-diagram--d2`,onclick:`
        const figure = this;
        const isFullscreen = figure.classList.contains('vpd-diagram--fullscreen');

        document.querySelectorAll('.vpd-diagram').forEach(diagram => {
          diagram.classList.remove('vpd-diagram--fullscreen');
        });

        if (!isFullscreen) {
          figure.classList.add('vpd-diagram--fullscreen');
        }
      `},[t(`img`,{src:`/notopia/pr/343/diagrams/d2-architecture-billing-diagram-f41ba47c16b4c5a2d47ab4638899a22b.svg`,alt:`d2 Diagram`,class:`vpd-diagram-image`})],-1),n(`<h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to “Events”">​</a></h2><p>Repo <code>Save</code> writes the aggregate&#39;s popped domain events into <code>outbox_messages</code> in the same transaction. <code>outbox.Forwarder</code> relays them to Kafka, keyed by the aggregate id (workspace id for the integration event). Topics are declared once in <code>internal/billing/component/eventtopic.go</code>.</p><h3 id="published" tabindex="-1">Published <a class="header-anchor" href="#published" aria-label="Permalink to “Published”">​</a></h3><table tabindex="0"><thead><tr><th>Topic</th><th>Payload</th><th>When</th></tr></thead><tbody><tr><td><code>events.integration.billing.subscription.changed</code></td><td><code>{workspaceId, plan, status}</code></td><td><code>SubscriptionStateChangedEvent</code>: recorded whenever a subscription&#39;s plan or status changes (not for duplicate checkouts)</td></tr><tr><td><code>events.internal.billing.{aggregate}.{event}</code></td><td>the domain event</td><td>every other domain event, e.g. <code>subscription.canceled_now</code>, <code>subscription.refund_requested</code>, <code>billing_account.payer_missing</code>, <code>price.created</code>, <code>plan.updated</code></td></tr></tbody></table><p>The <code>events.internal.*</code> topics are billing&#39;s own: only billing consumes them (see below).</p><h3 id="consumed" tabindex="-1">Consumed <a class="header-anchor" href="#consumed" aria-label="Permalink to “Consumed”">​</a></h3><table tabindex="0"><thead><tr><th>Topic</th><th>Use case</th></tr></thead><tbody><tr><td><code>events.integration.note.workspace.deleted</code></td><td><code>HandleWorkspaceDeleted</code></td></tr><tr><td><code>events.integration.authorization.user_workspace_role_updated</code></td><td><code>HandlePayerRemoved</code> (payer no longer owner)</td></tr><tr><td><code>events.integration.authorization.workspace_member_removed</code></td><td><code>HandlePayerRemoved</code></td></tr><tr><td><code>events.internal.billing.subscription.canceled_now</code></td><td><code>CancelProviderSubscription</code> (cancel at the provider)</td></tr><tr><td><code>events.internal.billing.subscription.refund_requested</code></td><td><code>SubmitRefund</code> (create the provider refund)</td></tr></tbody></table><p>One consumer group per topic. An undecodable payload or a permanent error (<code>notFound</code>, <code>invalid</code>) is logged and acked; other errors are retried.</p>`,8)]])}var c=r(o,[[`render`,s]]);export{a as __pageData,c as default};